package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.pool.Pool;
import net.officefloor.hq.app.pool.PoolMember;
import net.officefloor.hq.app.pool.PoolRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Merges one person into another (a steward only; neither retired, not the same person). The merged person's claims
 * move to the other, keeping their numbers and dates, listed after the other's in the order they were added and
 * losing any figure a statement bound; their name and aliases become the other's aliases; their patrons are added to
 * the other's and anyone naming them as patron names the other instead (never themselves, never twice); their pool
 * memberships move to the other (shares added where the other is a member already). Their statements, holds,
 * watchers and contact are dropped, and the merged person is removed.
 */
@Service
public class MergeService {

    private final PersonRepository people;
    private final PersonAliasRepository aliases;
    private final PersonPatronRepository patrons;
    private final PersonWatchRepository watches;
    private final ClaimRepository claims;
    private final StatementRepository statements;
    private final PoolRepository pools;
    private final PeriodRepository periods;
    private final RoleService roles;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public MergeService(PersonRepository people, PersonAliasRepository aliases, PersonPatronRepository patrons,
            PersonWatchRepository watches, ClaimRepository claims, StatementRepository statements,
            PoolRepository pools, PeriodRepository periods, RoleService roles, SheetService sheets,
            RollupService rollup, Audit audit) {
        this.people = people;
        this.aliases = aliases;
        this.patrons = patrons;
        this.watches = watches;
        this.claims = claims;
        this.statements = statements;
        this.pools = pools;
        this.periods = periods;
        this.roles = roles;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** Merge the person into the other; the other, as it now stands. */
    @Transactional
    public Person merge(String sheetId, String user, Long id, Long intoId) {
        Person from = people.findForUpdate(id, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, id));
        Person into = people.findForUpdate(intoId, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, intoId));
        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
            throw new PersonMergeRefusedException("Only a steward can merge people");
        }
        if (from.getId().equals(into.getId())) {
            throw new PersonMergeRefusedException(from.getName() + " cannot be merged into themselves");
        }
        if (from.isRetired() || into.isRetired()) {
            throw new PersonMergeRefusedException("A retired person cannot be merged");
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);

        // The claims, listed after the other's in the order they were added, each live again.
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, from.getId()).stream()
                .sorted(Comparator.comparingLong(Claim::getListed).thenComparing(Claim::getId))
                .toList();
        for (Claim claim : theirs) {
            claim.setPersonId(into.getId());
            claim.setStated(false, null);
            claim.setListed(sheets.nextListed(sheetId));
        }
        claims.saveAll(theirs);

        // The name and aliases become the other's aliases; the name is free once the person is removed.
        List<PersonAlias> theirAliases = aliases.findByPersonId(from.getId());
        theirAliases.forEach(a -> a.setPersonId(into.getId()));
        aliases.saveAll(theirAliases);

        // Patrons: the merged person's are added to the other's, and those naming them name the other instead.
        List<PersonPatron> all = patrons.findBySheetIdOrderByIdAsc(sheetId);
        Set<Long> intoPatrons = new HashSet<>();
        Set<String> pairs = new HashSet<>();
        for (PersonPatron p : all) {
            if (p.getPersonId().equals(into.getId())) {
                intoPatrons.add(p.getPatronId());
            }
            if (!p.getPersonId().equals(from.getId()) && !p.getPatronId().equals(from.getId())) {
                pairs.add(p.getPersonId() + ":" + p.getPatronId());
            }
        }
        List<PersonPatron> dropped = new ArrayList<>();
        List<PersonPatron> moved = new ArrayList<>();
        for (PersonPatron p : all) {
            if (!p.getPersonId().equals(from.getId()) && !p.getPatronId().equals(from.getId())) {
                continue;
            }
            Long person = p.getPersonId().equals(from.getId()) ? into.getId() : p.getPersonId();
            Long patron = p.getPatronId().equals(from.getId()) ? into.getId() : p.getPatronId();
            if (person.equals(patron) || !pairs.add(person + ":" + patron)) {
                dropped.add(p);
            } else {
                p.setPersonId(person);
                p.setPatronId(patron);
                moved.add(p);
            }
        }
        patrons.deleteAll(dropped);
        patrons.flush();
        patrons.saveAll(moved);

        // Pool memberships move, shares added where the other is a member already.
        for (Pool pool : pools.findBySheetIdOrderByIdAsc(sheetId)) {
            PoolMember membership = pool.getMembers().stream()
                    .filter(m -> m.getPersonId().equals(from.getId())).findFirst().orElse(null);
            if (membership == null) {
                continue;
            }
            PoolMember existing = pool.getMembers().stream()
                    .filter(m -> m.getPersonId().equals(into.getId())).findFirst().orElse(null);
            if (existing != null) {
                existing.setShare(existing.getShare().add(membership.getShare()));
                pool.getMembers().remove(membership);
            } else {
                membership.setPersonId(into.getId());
            }
            pools.saveAndFlush(pool);
        }

        // A closed period's fixed figures follow the claims.
        for (Period period : periods.findBySheetIdOrderByFromDateAscIdAsc(sheetId)) {
            if (period.getPersonTotals().containsKey(from.getId())) {
                period.mergePersonTotal(from.getId(), into.getId());
                periods.save(period);
            }
        }

        // Statements, watchers, holds and contact go with the person.
        statements.deleteAll(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, from.getId()));
        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from.getId()));
        claims.flush();
        people.delete(from);
        people.flush();
        aliases.saveAndFlush(new PersonAlias(sheetId, into.getId(), from.getName()));

        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + user
                + " from=" + from.getName() + " into=" + into.getName());
        rollup.recordChanges(sheetId, user, before);
        return into;
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The name as compared for uniqueness on the sheet: trimmed and lower-cased. */
    @Column(name = "name_key", nullable = false)
    private String nameKey;

    /** The person's grades, each from its from-date; the first one given has none. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "person_id", nullable = false)
    private List<PersonGrade> grades = new ArrayList<>();

    /** The person's own terms in whole days, ahead of their grade's and the sheet's; null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** The person's contact, trimmed and lower-cased; null when they have none. */
    @Column(name = "contact")
    private String contact;

    /** The date the person is retired from; null while not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The sheet's today when the person was added; null for a person added before that was kept. */
    @Column(name = "added_on")
    private LocalDate addedOn;

    /** The sheet's today when the person's retirement was recorded; null when not retired or recorded before that was kept. */
    @Column(name = "retired_on")
    private LocalDate retiredOn;

    /** The person's holds: their OPEN claims dated within one, not bound by a statement, count in no live total. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "person_id", nullable = false)
    private List<PersonHold> holds = new ArrayList<>();

    /** Raised by one on each save; a save of an older version is refused. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        setName(name);
        grades.add(new PersonGrade(grade, null));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    /** Keeps the name with the spaces before and after it removed. */
    public void setName(String name) {
        this.name = name.trim();
        this.nameKey = key(name);
    }

    /** The key a name is compared on: two names with the same key are the same name. */
    public static String key(String name) {
        return name.trim().toLowerCase(Locale.ROOT);
    }

    /** The person's grades, the undated one first and then by from-date. */
    public List<PersonGrade> getGrades() {
        return grades.stream()
                .sorted(Comparator.comparing(PersonGrade::getFromDate,
                        Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** The grade in force on the date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate date) {
        String grade = null;
        for (PersonGrade g : getGrades()) {
            if (g.getFromDate() == null || !g.getFromDate().isAfter(date)) {
                grade = g.getGrade();
            }
        }
        return grade;
    }

    /** Record the grade from the date, replacing the grade the person had from that same date. */
    public void setGrade(String grade, LocalDate fromDate) {
        for (PersonGrade g : grades) {
            if (Objects.equals(g.getFromDate(), fromDate)) {
                g.setGrade(grade);
                return;
            }
        }
        grades.add(new PersonGrade(grade, fromDate));
    }

    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    public String getContact() {
        return contact;
    }

    /** Keeps the contact trimmed and lower-cased; a blank one is none. */
    public void setContact(String contact) {
        this.contact = contactKey(contact);
    }

    /** The contact as kept: trimmed and lower-cased; null when blank. */
    public static String contactKey(String contact) {
        return contact == null || contact.isBlank() ? null : contact.trim().toLowerCase(Locale.ROOT);
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    /** A person with a retirement date counts as retired at once, whatever the date. */
    public boolean isRetired() {
        return retiredFrom != null;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    public LocalDate getAddedOn() {
        return addedOn;
    }

    public void setAddedOn(LocalDate addedOn) {
        this.addedOn = addedOn;
    }

    /** Record the retirement from the date, recorded while the sheet's today was {@code on}. */
    public void retire(LocalDate retiredFrom, LocalDate on) {
        this.retiredFrom = retiredFrom;
        this.retiredOn = on;
    }

    /** Whether the person had been added by the end of the date: added while the sheet's today was on or before it. */
    public boolean addedBy(LocalDate date) {
        return addedOn == null || !addedOn.isAfter(date);
    }

    /**
     * Whether the person's retirement date is reached on the date as they stood at the end of it: retired by a
     * retirement recorded while the sheet's today was on or before it, from that date or earlier.
     */
    public boolean retiredAsOf(LocalDate date) {
        return retiredOn(date) && (retiredOn == null || !retiredOn.isAfter(date));
    }

    /** Whether the date is within a hold the person had by the end of {@code asOf}. */
    public boolean heldAsOf(LocalDate date, LocalDate asOf) {
        return holds.stream().anyMatch(h -> h.madeBy(asOf) && h.covers(date));
    }

    /** Whether the person's retirement date is reached on the date: it is on or after it. */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date != null && !date.isBefore(retiredFrom);
    }

    /** Whether the person has any hold. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** The person's holds by from-date, in the order they were added. */
    public List<PersonHold> getHolds() {
        return holds.stream().sorted(Comparator.comparing(PersonHold::getFromDate)).toList();
    }

    /** Add a hold from the date to the date (null: it does not end), added while the sheet's today was {@code on}. */
    public void addHold(LocalDate fromDate, LocalDate toDate, LocalDate on) {
        holds.add(new PersonHold(fromDate, toDate, on));
    }

    /** Whether the date is within any of the person's holds. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /**
     * Whether the claim counts in the live totals: an OPEN, PENDING or SETTLED one, but an OPEN or PENDING one dated
     * within a hold, or once the person's retirement date is reached on the sheet's today, not unless a statement binds
     * it, and an OPEN one deferred on the sheet's today not at all.
     */
    public boolean counts(Claim claim, LocalDate today) {
        ClaimStatus status = claim.getStatus();
        return status.counts()
                && !(status.isOpen() && !claim.isBound() && (heldOn(claim.getDate()) || retiredOn(today)))
                && !claim.isDeferredOn(today);
    }

    /**
     * Whether the claim counts in a period's due-total, given the status it had at the end of the period's last day
     * (null when it was added after): an OPEN, PENDING or SETTLED one, but one open then and still open now and dated
     * within a hold, or once the person's retirement date is reached on the sheet's today, not unless a statement binds
     * it, and an OPEN one deferred on the sheet's today not at all.
     */
    public boolean countsAsOf(Claim claim, ClaimStatus status, LocalDate today) {
        return status != null && status.counts() && !(status.isOpen() && claim.getStatus().isOpen()
                && !claim.isBound() && (heldOn(claim.getDate()) || retiredOn(today))) && !claim.isDeferredOn(today);
    }

    /** Refused when the person is retired and the date is after their retirement date. */
    public void requireClaimable(LocalDate date) {
        if (retiredFrom != null && date.isAfter(retiredFrom)) {
            throw new PersonRetiredException(name, retiredFrom, date);
        }
    }

    public long getVersion() {
        return version;
    }
}

